(function(e){e.JobLabContent=Object.assign(e.JobLabContent||{},{"KK-063":{scenario:{company:"Riverstone Data Platform",supervisor:{name:"Bùi Văn Hiếu",role:{vi:"Trưởng nhóm Kỹ thuật Dữ liệu",en:"Data Engineering Lead"}},ref_code:"ETL-0632",title:{vi:"Nạp lũy đẳng. Đối soát từng dòng. Không tắt kiểm tra.",en:"Idempotent loads. Reconcile every row. Never mute checks."},brief:{vi:"Bạn phụ trách job nạp dữ liệu đơn hàng hằng ngày ETL-0632 vào bảng fact_orders (khóa chính order_id). Trước lần nạp, bảng đích có 5.400.000 dòng. Bản trích xuất hôm nay có 86.500 dòng, trong đó 12.300 dòng là bản cập nhật của order_id đã tồn tại (đổi trạng thái giao hàng). Kiểm tra chất lượng báo trùng khóa. Đối chiếu cấu hình nháp với thiết kế đã duyệt, sửa chế độ ghi và số dòng kỳ vọng của bảng đích, rồi lập báo cáo có căn cứ.",en:"You own daily order load job ETL-0632 into table fact_orders (primary key order_id). Before the load the target had 5,400,000 rows. Today's extract has 86,500 rows, of which 12,300 are updates to existing order_ids (delivery status changes). The quality check reports duplicate keys. Compare the draft config with the approved design, fix the write mode and the expected target row count, then write an evidence-based report."},reference_title:{vi:"Thiết kế nạp dữ liệu đã duyệt · ETL-0632",en:"Approved load design · ETL-0632"},fields:[{id:"WRITE_MODE",label:{vi:"Chế độ ghi vào bảng đích",en:"Target write mode"},initial:"append",expected:"merge",choices:["append","merge","overwrite"],reference:"Thiết kế nạp dữ liệu",hint:{vi:"Dữ liệu tăng dần có bản ghi cập nhật theo khóa chính phải được upsert để chạy lại không sinh trùng.",en:"Incremental data with key-based updates must be upserted so reruns never create duplicates."}},{id:"TARGET_ROWS",label:{vi:"Số dòng kỳ vọng sau nạp",en:"Expected rows after load"},initial:"5486500",expected:"5474200",reference:"Bảng đối soát số dòng",ref_value:{vi:"Trước nạp 5.400.000; trích xuất 86.500; trong đó 12.300 order_id đã tồn tại",en:"Before load 5,400,000; extract 86,500; of which 12,300 order_ids already exist"},hint:{vi:"Chỉ khóa mới làm tăng số dòng; bản ghi trùng khóa chỉ cập nhật dòng cũ.",en:"Only new keys add rows; records with existing keys just update the old row."}}],sop32:{vi:"Số dòng đích kỳ vọng = số dòng trước nạp + (số dòng trích xuất - số dòng có khóa đã tồn tại); bản ghi trùng khóa chỉ cập nhật. Lệch đối soát thì không công bố dữ liệu.",en:"Expected target rows = rows before load + (extracted rows - rows with existing keys); existing keys are only updated. If reconciliation fails, data is not published."},context:{label:"ORCHESTRATOR / ETL-0632",metrics:[{label:{vi:"Dòng trước nạp",en:"Rows before load"},value:"5,400,000"},{label:{vi:"Dòng trích xuất",en:"Extracted rows"},value:"86,500"},{label:{vi:"Khóa đã tồn tại",en:"Existing keys"},value:"12,300"}]},crisis:{vi:"Trưởng phòng kinh doanh nhắn: “Tắt cái kiểm tra chất lượng đang báo đỏ đi cho dashboard doanh thu lên kịp họp Hội đồng quản trị 9 giờ sáng. Trùng có chút xíu, họp xong sửa.”",en:"The head of sales messages you: “Turn off that red quality check so the revenue dashboard is ready for the 9 a.m. board meeting. The duplicates are tiny, fix it after the meeting.”"},options:{safe:{vi:"Không tắt kiểm tra, không công bố số sai; báo trưởng nhóm và chủ sở hữu dữ liệu, chuyển sang merge, chạy lại có đối soát và thông báo giờ dữ liệu đúng sẵn sàng.",en:"Keep the check on and publish no wrong figures; inform the lead and data owner, switch to merge, rerun with reconciliation and announce when correct data is ready."},shortcut:{vi:"Tắt kiểm tra chất lượng, công bố dashboard cho kịp họp rồi sửa sau.",en:"Disable the quality check, publish the dashboard for the meeting and fix it later."},wait:{vi:"Để job lỗi nguyên đó, không báo ai và chờ phòng kinh doanh hỏi lại.",en:"Leave the job failing, tell no one and wait for Sales to ask again."}},questions:{vi:["Vì sao chế độ ghi phải là merge và bảng đích đúng là 5474200 dòng? Bạn đối soát bằng những số nào?","Nếu bị ép tắt kiểm tra chất lượng để kịp họp, bạn bảo vệ độ tin cậy số liệu và thông báo cho người dùng dữ liệu thế nào?"],en:["Why must the write mode be merge and the target hold 5474200 rows? Which figures do you reconcile?","If pressed to disable quality checks for a meeting, how do you protect data trust and inform data consumers?"]},hints:{vi:["Đọc cấu hình job và báo cáo chất lượng trước, xác định vì sao khóa chính bị trùng.","Tách bản trích xuất thành khóa mới và khóa đã tồn tại rồi áp công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: kiểm tra chất lượng là cổng chặn; chỉ chủ sở hữu dữ liệu mới quyết định công bố có điều kiện."],en:["Read the job config and quality report first and find why the primary key is duplicated.","Split the extract into new and existing keys, then apply the formula in SOP 3.2.","Re-read SOP 4.2: quality checks are a gate; only the data owner may approve a conditional release."]},terminal:{system:"pipeline-ctl",settable:["WRITE_MODE","TARGET_ROWS"],commands:[{cmd:"status",out:{vi:"DAG orders_daily: load SUCCESS, dq_check FAILED - fact_orders có 12.300 order_id trùng; dashboard doanh thu đang chờ dữ liệu.",en:"DAG orders_daily: load SUCCESS, dq_check FAILED - fact_orders has 12,300 duplicate order_ids; the revenue dashboard is waiting."}},{cmd:"cat job_config.yaml",out:{vi:"Cấu hình job: source orders_cdc | target fact_orders | write_mode append | primary_key order_id | partition order_date",en:"Job config: source orders_cdc | target fact_orders | write_mode append | primary_key order_id | partition order_date"}},{cmd:"cat dq_report.txt",out:{vi:"uniqueness(order_id): FAIL - 12.300 khóa xuất hiện 2 lần | row_count hiện tại 5.486.500, chưa khớp đối soát.",en:"uniqueness(order_id): FAIL - 12,300 keys appear twice | current row_count 5,486,500, reconciliation mismatch."}},{cmd:"cat extract_manifest.json",out:{vi:"Lô 2026-11-03: 86.500 dòng | 12.300 order_id đã có trong fact_orders (cập nhật trạng thái) | còn lại là đơn mới.",en:"Batch 2026-11-03: 86,500 rows | 12,300 order_ids already in fact_orders (status updates) | the rest are new orders."}},{cmd:"cat design_doc.md",out:{vi:"fact_orders lưu trạng thái hiện tại của đơn: mỗi order_id đúng 1 dòng; job phải lũy đẳng, chạy lại không đổi kết quả.",en:"fact_orders holds each order's current state: exactly 1 row per order_id; the job must be idempotent, reruns change nothing."}}]}},learning:{summary:{vi:"Kỹ sư đường ống dữ liệu thiết kế, xây dựng và vận hành hệ thống thu thập, biến đổi, lưu trữ dữ liệu ở quy mô lớn để phân tích, báo cáo và học máy có dữ liệu đúng, đủ, kịp thời. Họ làm việc với ETL/ELT, CDC, kho dữ liệu, hồ dữ liệu, điều phối job và kiểm soát chất lượng. Nghề đòi hỏi SQL vững, lập trình, hiểu mô hình dữ liệu, tư duy lũy đẳng và kỷ luật quản trị dữ liệu.",en:"A data engineer designs, builds and runs large-scale systems that ingest, transform and store data so analytics, reporting and machine learning get correct, complete and timely data. The work covers ETL/ELT, CDC, warehouses, data lakes, job orchestration and quality control. The role requires strong SQL, programming, data modelling, an idempotency mindset and data governance discipline."},responsibilities:{vi:["Thiết kế và xây đường ống ETL/ELT, CDC từ hệ thống nguồn vào kho và hồ dữ liệu.","Mô hình hóa dữ liệu (bảng sự kiện, bảng chiều, SCD), tối ưu phân vùng và định dạng lưu trữ.","Viết kiểm tra chất lượng, đối soát số dòng và tổng tiền giữa nguồn và đích.","Điều phối, giám sát job, xử lý sự cố, chạy lại an toàn và giữ SLA dữ liệu.","Quản lý quyền truy cập, che dữ liệu nhạy cảm, lưu dòng dõi dữ liệu và tài liệu hóa."],en:["Design and build ETL/ELT and CDC pipelines from source systems into the warehouse and lake.","Model data (facts, dimensions, SCDs) and tune partitioning and storage formats.","Write quality checks and reconcile row counts and amounts between source and target.","Orchestrate and monitor jobs, handle incidents, rerun safely and meet data SLAs.","Manage access, mask sensitive data, record lineage and document everything."]},competencies:[{name:{vi:"SQL & mô hình dữ liệu",en:"SQL & data modelling"},desc:{vi:"Viết truy vấn hiệu quả, thiết kế độ hạt, khóa và bảng chiều đúng nhu cầu phân tích.",en:"Write efficient queries and design grain, keys and dimensions that fit analytics needs."}},{name:{vi:"Xử lý phân tán",en:"Distributed processing"},desc:{vi:"Tối ưu job Spark: phân vùng, xáo trộn dữ liệu, lệch khóa và bộ nhớ.",en:"Tune Spark jobs: partitioning, shuffles, key skew and memory."}},{name:{vi:"Độ tin cậy đường ống",en:"Pipeline reliability"},desc:{vi:"Thiết kế job lũy đẳng, chạy lại và backfill an toàn, có cảnh báo và runbook.",en:"Design idempotent jobs with safe reruns and backfills, alerts and runbooks."}},{name:{vi:"Chất lượng & quan sát dữ liệu",en:"Data quality & observability"},desc:{vi:"Kiểm tra tính duy nhất, đầy đủ, hợp lệ, kịp thời; đối soát nguồn và đích.",en:"Check uniqueness, completeness, validity and timeliness; reconcile source and target."}},{name:{vi:"Quản trị & bảo mật dữ liệu",en:"Data governance & security"},desc:{vi:"Phân quyền tối thiểu, che dữ liệu cá nhân, lưu dòng dõi và không bỏ qua cổng kiểm soát.",en:"Apply least privilege, mask personal data, track lineage and never bypass control gates."}}],knowledge:{vi:["Mô hình hóa chiều theo Kimball: bảng sự kiện, bảng chiều, độ hạt, SCD Type 1 và Type 2.","ETL/ELT, CDC, nạp tăng dần theo watermark, upsert bằng MERGE và thiết kế lũy đẳng.","Kiến trúc lakehouse nhiều tầng (bronze, silver, gold), định dạng cột Parquet và phân vùng.","DAMA-DMBOK: các chiều chất lượng dữ liệu (đầy đủ, duy nhất, hợp lệ, kịp thời, nhất quán).","Xử lý phân tán với Apache Spark, điều phối bằng DAG và giám sát SLA.","Nghị định 13/2023/NĐ-CP: phân quyền tối thiểu, che và mã hóa dữ liệu cá nhân trong đường ống."],en:["Kimball dimensional modelling: facts, dimensions, grain, SCD Type 1 and Type 2.","ETL/ELT, CDC, watermark-based incremental loads, MERGE upserts and idempotent design.","Multi-layer lakehouse (bronze, silver, gold), Parquet columnar format and partitioning.","DAMA-DMBOK data quality dimensions (completeness, uniqueness, validity, timeliness, consistency).","Distributed processing with Apache Spark, DAG orchestration and SLA monitoring.","Vietnam Decree 13/2023/ND-CP: least privilege, masking and encrypting personal data in pipelines."]},tools:["SQL","Apache Spark","Apache Airflow","dbt","Apache Kafka","Python"],tools_en:["SQL","Apache Spark","Apache Airflow","dbt","Apache Kafka","Python"],kpis:{vi:["Tỷ lệ job hoàn thành đúng SLA dữ liệu.","Số sự cố chất lượng dữ liệu lọt tới người dùng cuối.","Thời gian khôi phục khi job lỗi (MTTR).","Chi phí tính toán trên mỗi TB dữ liệu xử lý."],en:["Share of jobs meeting the data SLA.","Data quality incidents reaching end users.","Mean time to recover from job failures (MTTR).","Compute cost per TB processed."]},day:[{time:"07:30",vi:"Kiểm tra job chạy đêm và cảnh báo chất lượng dữ liệu trước giờ người dùng truy cập.",en:"Check overnight jobs and data quality alerts before users log in."},{time:"09:00",vi:"Xử lý job lỗi, sửa nguyên nhân và chạy lại có đối soát.",en:"Fix a failed job at the root cause and rerun with reconciliation."},{time:"11:00",vi:"Thiết kế bảng chiều khách hàng SCD Type 2 cùng chuyên viên BI.",en:"Design an SCD Type 2 customer dimension with the BI analyst."},{time:"14:00",vi:"Rà soát pull request mô hình biến đổi, kiểm tra kiểm thử dữ liệu đi kèm.",en:"Review a transformation model pull request and its data tests."},{time:"16:00",vi:"Tối ưu job Spark bị lệch khóa, giảm thời gian chạy và chi phí.",en:"Tune a skewed Spark job to cut run time and cost."}],mistakes:{vi:["Dùng append cho dữ liệu có cập nhật theo khóa khiến bảng đích sinh trùng khi chạy lại.","Tắt kiểm tra chất lượng để kịp hạn thay vì sửa nguyên nhân gốc.","Sao chép dữ liệu cá nhân chưa che sang môi trường phát triển để gỡ lỗi."],en:["Using append for key-updated data so reruns duplicate rows in the target.","Disabling quality checks to meet a deadline instead of fixing the root cause.","Copying unmasked personal data into development to debug."]},career:[{vi:"Kỹ sư dữ liệu tập sự",en:"Junior data engineer"},{vi:"Kỹ sư dữ liệu",en:"Data engineer"},{vi:"Kỹ sư dữ liệu cấp cao / trưởng nhóm",en:"Senior data engineer / team lead"},{vi:"Kiến trúc sư dữ liệu / giám đốc kỹ thuật dữ liệu",en:"Data architect / head of data engineering"}],glossary:[{term:"Idempotent",vi:"Tính chất của job: chạy lại nhiều lần với cùng đầu vào cho cùng kết quả.",en:"Job property where repeated runs with the same input give the same result."},{term:"CDC",vi:"Thu thập thay đổi dữ liệu (thêm, sửa, xóa) từ hệ thống nguồn theo thời gian gần thực.",en:"Change data capture of inserts, updates and deletes from source systems in near real time."},{term:"MERGE / Upsert",vi:"Lệnh cập nhật dòng đã có theo khóa và chèn dòng mới chưa có trong một thao tác.",en:"Statement that updates existing rows by key and inserts new ones in a single operation."},{term:"SCD Type 2",vi:"Kỹ thuật lưu lịch sử bảng chiều bằng cách thêm dòng mới kèm hiệu lực từ ngày, đến ngày.",en:"Dimension history technique adding a new row with valid-from and valid-to dates."},{term:"Watermark",vi:"Mốc thời gian hoặc giá trị lớn nhất đã nạp, dùng để lấy phần dữ liệu tăng thêm.",en:"The latest time or value already loaded, used to fetch the next increment."}],quiz:[{q:{vi:"Bảng đích có 1.200.000 dòng. Lô mới có 30.000 dòng, trong đó 4.500 khóa đã tồn tại. Sau khi MERGE, bảng có bao nhiêu dòng?",en:"The target has 1,200,000 rows. A new batch has 30,000 rows, 4,500 with existing keys. How many rows after MERGE?"},options:{vi:["1230000","1195500","1225500","1204500"],en:["1230000","1195500","1225500","1204500"]},answer:2,explain:{vi:"1.200.000 + (30.000 - 4.500) = 1.225.500; khóa đã tồn tại chỉ được cập nhật.",en:"1,200,000 + (30,000 - 4,500) = 1,225,500; existing keys are only updated."}},{q:{vi:"Khi nào một job dữ liệu được gọi là lũy đẳng?",en:"When is a data job called idempotent?"},options:{vi:["Chạy lại nhiều lần với cùng đầu vào cho cùng kết quả","Mỗi lần chạy nhanh hơn lần trước","Luôn ghi đè toàn bộ bảng","Không bao giờ bị lỗi"],en:["Repeated runs with the same input give the same result","Each run is faster than the last","It always overwrites the whole table","It never fails"]},answer:0,explain:{vi:"Lũy đẳng giúp chạy lại, backfill an toàn mà không sinh trùng hay mất dữ liệu.",en:"Idempotency allows safe reruns and backfills without duplicates or data loss."}},{q:{vi:"Cần báo cáo doanh thu theo địa chỉ khách hàng tại thời điểm mua dù sau đó khách đổi địa chỉ. Dùng loại SCD nào?",en:"Revenue must be reported by the customer's address at purchase time even after it changes. Which SCD type fits?"},options:{vi:["SCD Type 0","SCD Type 1","Không cần bảng chiều","SCD Type 2"],en:["SCD Type 0","SCD Type 1","No dimension needed","SCD Type 2"]},answer:3,explain:{vi:"SCD Type 2 giữ lịch sử bằng dòng mới có hiệu lực theo thời gian; Type 1 ghi đè làm mất lịch sử.",en:"SCD Type 2 keeps history with time-bounded rows; Type 1 overwrites and loses history."}},{q:{vi:"Kiểm tra chất lượng báo trùng khóa ngay trước cuộc họp quan trọng và bạn bị yêu cầu tắt nó. Bạn làm gì?",en:"A quality check flags duplicate keys right before a key meeting and you are told to disable it. What do you do?"},options:{vi:["Tắt kiểm tra cho kịp họp","Giữ kiểm tra, báo trưởng nhóm và chủ sở hữu dữ liệu, sửa và chạy lại có đối soát","Xóa tay các dòng trùng trên production, không ghi log","Gửi dashboard số liệu cũ mà không ghi chú"],en:["Disable it for the meeting","Keep it, escalate to the lead and data owner, fix and rerun with reconciliation","Delete duplicates by hand in production without logging","Send the old dashboard without any note"]},answer:1,explain:{vi:"Cổng chất lượng bảo vệ quyết định của lãnh đạo; số liệu sai gây hại lớn hơn chậm vài giờ.",en:"Quality gates protect leadership decisions; wrong numbers do more harm than a few hours' delay."}}]}}})})(window.KKR);
